# Generated by build.py from recipe.yml for recipe http-tell-transient-from-permanent-errors. Do not edit.
Set-Location $PSScriptRoot
$server0 = Start-Process surl -ArgumentList '-v', '--log-file', 'surl.log', '--directory', 'site', '--fault', '"error;scheme=http;reply=503;path=/report.txt;times=1"', '--fault', '"error;scheme=http;reply=500;path=/broken.txt"', '--fault', '"error;scheme=http;reply=403;path=/locked.txt"', '--fault', '"error;scheme=http;reply=503;path=/later.txt;times=1"', 'http://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -s -f --retry 2 --retry-delay 1 -w "%{http_code} %{num_retries}\n" http://127.0.0.1:8080/report.txt } finally { Stop-Process $server0 }
